export function validateWarehouseSave(record){
 const valid=(test)=>{if(!test)throw Error('Cette sauvegarde logistique est incomplète ou incompatible.');};
 const integer=(n,min=0,max=Number.MAX_SAFE_INTEGER)=>Number.isSafeInteger(n)&&n>=min&&n<=max;
 const finite=n=>typeof n==='number'&&Number.isFinite(n);
 const point=p=>Array.isArray(p)&&p.length===2&&p.every(n=>finite(n)&&Math.abs(n)<=40);
 const s=record.state,ids=['tech','books','home','toys','beauty','fashion'];valid(s?.kind==='fulfillment'&&s.version===1&&integer(s.day,1)&&integer(s.minute,300,1320)&&[0,1,3,6].includes(s.speed)&&integer(s.seed)&&integer(s.nextId,1));
 for(const key of ['money','initialCash','startingUnits','receivedUnits','soldUnits','reputation','arrivalCredit','dayStartCash','lastDispatch'])valid(finite(s[key]));valid(s.reputation>=0&&s.reputation<=100);
 valid(['standard','express','volume'].includes(s.plan)&&typeof s.acceptOrders==='boolean'&&['deadline','express','fifo','sector'].includes(s.priority)&&[30,60,120].includes(s.dispatchEvery)&&integer(s.benches,1,3)&&integer(s.robotTarget,0,8));
 for(const key of ['products','orders','shipments','workers','vans','contracts','history','log'])valid(Array.isArray(s[key]));valid(s.products.length===6&&s.orders.length<=2000&&s.workers.length<=64&&s.shipments.length<=2000&&s.vans.length>=1&&s.vans.length<=4);
 for(const [i,p]of s.products.entries()){valid(p.id===ids[i]&&['cost','price'].every(k=>finite(p[k])&&p[k]>0));for(const key of ['onHand','reserved','ordered','sold','capacity'])valid(integer(p[key]));valid(p.onHand<=p.capacity&&p.reserved<=p.onHand&&p.capacity>=240&&p.capacity<=960);}
 const orderIds=new Set(),workerIds=new Set(),shipmentIds=new Set(),vanIds=new Set();
 for(const o of s.orders){valid(integer(o.id,1)&&!orderIds.has(o.id));orderIds.add(o.id);valid(['queued','picking','await_pack','packing','ready','in_transit','delivered'].includes(o.stage)&&['standard','express'].includes(o.channel)&&['north','east','west'].includes(o.area)&&integer(o.created)&&integer(o.deadline,o.created)&&finite(o.value)&&o.value>0&&typeof o.late==='boolean');valid(Array.isArray(o.lines)&&o.lines.length>0&&o.lines.length<=6&&new Set(o.lines.map(l=>l.productId)).size===o.lines.length);for(const l of o.lines)valid(ids.includes(l.productId)&&integer(l.quantity,1,12)&&integer(l.picked,0,l.quantity));if(o.stage==='queued')valid(o.lines.every(l=>l.picked===0));if(!['queued','picking'].includes(o.stage))valid(o.lines.every(l=>l.picked===l.quantity));if(o.stage==='delivered')valid(integer(o.deliveredAt,o.created)&&finite(o.paid)&&o.paid>0);}
 for(const t of s.shipments){valid(integer(t.id,1)&&!shipmentIds.has(t.id));shipmentIds.add(t.id);valid(ids.includes(t.productId)&&integer(t.quantity,24,960)&&integer(t.remaining,0,t.quantity)&&integer(t.reserved,0,t.remaining)&&integer(t.eta)&&typeof t.express==='boolean'&&finite(t.cost)&&t.cost>0);}
 const phases=['idle','to_rack','collecting','to_pack','to_truck','loading','to_stock','to_pickup','to_bench','packing','to_staging','driving','to_home'];
 for(const w of s.workers){valid(integer(w.id,1)&&!workerIds.has(w.id));workerIds.add(w.id);valid(['receiving','picking','packing','drivers'].includes(w.role)&&typeof w.robot==='boolean'&&(!w.robot||w.role==='picking')&&typeof w.retiring==='boolean'&&phases.includes(w.phase)&&point(w.pos)&&Array.isArray(w.path)&&w.path.length<=300&&w.path.every(point)&&finite(w.remaining)&&integer(w.cargo));if(w.target!==null)valid(point(w.target));if(w.phase==='idle')valid(w.job===null&&w.cargo===0);if(w.role==='picking'&&!['idle','to_home'].includes(w.phase))valid(orderIds.has(w.job)&&s.orders.find(o=>o.id===w.job).worker===w.id&&integer(w.line,0,6));if(w.role==='packing'&&!['idle','to_home'].includes(w.phase))valid(orderIds.has(w.job)&&s.orders.find(o=>o.id===w.job).worker===w.id&&integer(w.bench,0,s.benches-1));if(w.role==='receiving'&&!['idle','to_home'].includes(w.phase))valid(shipmentIds.has(w.shipment)&&ids.includes(w.productId)&&integer(w.quantity,1,48));}
 for(const role of ['receiving','picking','packing','drivers'])valid(integer(s.staff[role],0,12)&&s.workers.filter(w=>!w.robot&&!w.retiring&&w.role===role).length===s.staff[role]);valid(s.workers.filter(w=>w.robot&&!w.retiring).length===s.robotTarget);
 for(const p of s.products){const expected=s.orders.filter(o=>o.stage==='picking').reduce((n,o)=>n+o.lines.filter(l=>l.productId===p.id).reduce((m,l)=>m+l.quantity-l.picked,0),0);valid(p.reserved===expected);const incoming=s.shipments.filter(t=>t.productId===p.id).reduce((n,t)=>n+t.remaining,0)+s.workers.filter(w=>w.role==='receiving'&&w.productId===p.id).reduce((n,w)=>n+w.cargo,0);valid(p.ordered===incoming);}
 for(const v of s.vans){valid(integer(v.id,1)&&!vanIds.has(v.id));vanIds.add(v.id);valid(integer(v.capacity,1,48)&&['idle','loading','outbound','returning'].includes(v.phase)&&finite(v.remaining)&&Array.isArray(v.orders)&&v.orders.length<=v.capacity&&new Set(v.orders).size===v.orders.length&&v.orders.every(id=>orderIds.has(id)));if(v.phase!=='idle')valid(workerIds.has(v.driver)&&s.workers.find(w=>w.id===v.driver).role==='drivers');if(['loading','outbound'].includes(v.phase))valid(v.orders.every(id=>s.orders.find(o=>o.id===id).stage==='in_transit'));}
 for(const o of s.orders){if(o.worker!==null)valid(workerIds.has(o.worker));if(o.stage==='in_transit')valid(s.vans.filter(v=>['loading','outbound'].includes(v.phase)&&v.orders.includes(o.id)).length===1);}
 for(const o of s.orders){if(['picking','packing'].includes(o.stage)){const w=s.workers.find(w=>w.id===o.worker);valid(w&&w.job===o.id&&w.role===(o.stage==='picking'?'picking':'packing'));}}
 for(const w of s.workers){if(w.role==='drivers'){valid(['idle','driving'].includes(w.phase));if(w.phase==='driving')valid(s.vans.some(v=>v.id===w.job&&v.driver===w.id&&v.phase!=='idle'));}if(w.role==='picking'&&!['idle','to_home'].includes(w.phase)){const o=s.orders.find(o=>o.id===w.job);valid(['to_rack','collecting','to_pack'].includes(w.phase)&&w.cargo===o.lines.reduce((n,l)=>n+l.picked,0));}if(w.role==='receiving'&&!['idle','to_home'].includes(w.phase))valid(w.cargo===(w.phase==='to_stock'?w.quantity:0));}
 const globalIds=[...orderIds,...workerIds,...shipmentIds,...vanIds,...s.contracts.map(c=>c.id)];valid(new Set(globalIds).size===globalIds.length&&s.nextId>Math.max(0,...globalIds));
 for(const t of s.shipments)valid(t.reserved===s.workers.filter(w=>w.shipment===t.id&&['to_truck','loading'].includes(w.phase)).reduce((n,w)=>n+w.quantity,0));
 valid(s.layout&&typeof s.layout==='object'&&!Array.isArray(s.layout)&&Object.keys(s.layout).length<=9);for(const [key,p]of Object.entries(s.layout))valid((key.startsWith('rack:')&&ids.includes(key.slice(5))||/^pack:[0-2]$/.test(key))&&finite(p.x)&&finite(p.z)&&Math.abs(p.x)<=16&&Math.abs(p.z)<=10&&[0,Math.PI/2].includes(p.rotation));
 for(const c of s.contracts)valid(integer(c.id,1)&&['offered','accepted','expired','completed','failed'].includes(c.status)&&ids.includes(c.productId)&&integer(c.count,1,30)&&integer(c.quantity,1,12)&&Array.isArray(c.orders)&&(c.status!=='accepted'||c.orders.length===c.count&&c.orders.every(id=>orderIds.has(id)))&&[c.opens,c.expires,c.deadline,c.bonus].every(finite));
 for(const key of ['daily','totals']){valid(s[key]&&typeof s[key]==='object');for(const value of Object.values(s[key]))valid(finite(value)&&value>=0);}
 valid(record.preferences&&typeof record.preferences.checkoutSound==='boolean');return record;
}
